Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "config": {
    "background": "transparent",
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "axis": {
      "labelColor": "#9AA6B0",
      "labelFont": "Segoe UI",
      "labelFontSize": 10,
      "titleColor": "#9AA6B0",
      "titleFont": "Segoe UI",
      "titleFontWeight": "normal",
      "titleFontSize": 10,
      "domain": false,
      "ticks": false,
      "gridColor": "#2C363E"
    },
    "legend": {
      "labelColor": "#9AA6B0",
      "titleColor": "#9AA6B0",
      "labelFont": "Segoe UI"
    },
    "title": {
      "color": "#C9D3DB",
      "font": "Segoe UI Semibold",
      "fontSize": 12,
      "fontWeight": "normal",
      "anchor": "start",
      "offset": 12
    },
    "locale": {
      "number": {
        "decimal": ",",
        "thousands": ".",
        "grouping": [
          3
        ],
        "currency": [
          "R$ ",
          ""
        ]
      },
      "time": {
        "dateTime": "%A, %e de %B de %Y. %X",
        "date": "%d/%m/%Y",
        "time": "%H:%M:%S",
        "periods": [
          "AM",
          "PM"
        ],
        "days": [
          "Domingo",
          "Segunda",
          "Terça",
          "Quarta",
          "Quinta",
          "Sexta",
          "Sábado"
        ],
        "shortDays": [
          "Dom",
          "Seg",
          "Ter",
          "Qua",
          "Qui",
          "Sex",
          "Sáb"
        ],
        "months": [
          "Janeiro",
          "Fevereiro",
          "Março",
          "Abril",
          "Maio",
          "Junho",
          "Julho",
          "Agosto",
          "Setembro",
          "Outubro",
          "Novembro",
          "Dezembro"
        ],
        "shortMonths": [
          "Jan",
          "Fev",
          "Mar",
          "Abr",
          "Mai",
          "Jun",
          "Jul",
          "Ago",
          "Set",
          "Out",
          "Nov",
          "Dez"
        ]
      }
    }
  },
  "title": {
    "text": "Onde a sucata está parada · kg em aberto por praça e faixa de atraso"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "Kg",
          "as": "tot"
        }
      ],
      "groupby": [
        "Municipio"
      ]
    },
    {
      "calculate": "datum[''Municipio''] + ''  '' + format(datum.tot / 1000, '',.1f'') + '' t''",
      "as": "praca"
    },
    {
      "calculate": "format(datum[''Lanc''], '',.0f'') + '' lanç.''",
      "as": "lanctxt"
    }
  ],
  "encoding": {
    "x": {
      "field": "Faixa",
      "type": "ordinal",
      "sort": {
        "field": "Ordem",
        "op": "min",
        "order": "ascending"
      },
      "axis": {
        "orient": "top",
        "title": null,
        "labelColor": "#F2F4F5",
        "labelAngle": 0,
        "labelFontSize": 11
      }
    },
    "y": {
      "field": "praca",
      "type": "nominal",
      "sort": {
        "field": "tot",
        "op": "max",
        "order": "descending"
      },
      "axis": {
        "title": null,
        "labelColor": "#F2F4F5",
        "labelFontSize": 11,
        "labelPadding": 10
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rect",
        "cornerRadius": 4,
        "stroke": "#1A2026",
        "strokeWidth": 4
      },
      "encoding": {
        "color": {
          "field": "Kg",
          "type": "quantitative",
          "scale": {
            "range": [
              "#252E36",
              "#6B4416",
              "#FF8C00"
            ],
            "interpolate": "rgb"
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "Municipio",
            "title": "Praça"
          },
          {
            "field": "Faixa",
            "title": "Atraso"
          },
          {
            "field": "Kg",
            "format": ",.0f",
            "title": "kg em aberto"
          },
          {
            "field": "Lanc",
            "format": ",.0f",
            "title": "Lançamentos"
          },
          {
            "field": "Clientes",
            "format": ",.0f"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "datum[''Ordem''] == 4 && datum[''Kg''] > 0"
        }
      ],
      "mark": {
        "type": "rect",
        "cornerRadius": 4,
        "fill": null,
        "stroke": "#E5484D",
        "strokeWidth": 1.5
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 14,
        "fontWeight": 600,
        "dy": -6
      },
      "encoding": {
        "text": {
          "field": "Kg",
          "format": ",.0f"
        },
        "color": {
          "condition": {
            "test": "datum[''Kg''] > 2200",
            "value": "#1A2026"
          },
          "value": "#F2F4F5"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 9,
        "dy": 10
      },
      "encoding": {
        "text": {
          "field": "lanctxt"
        },
        "color": {
          "condition": {
            "test": "datum[''Kg''] > 2200",
            "value": "#3A2A16"
          },
          "value": "#9AA6B0"
        }
      }
    }
  ]
}'
